// Generated by `auth generate` (see auth.config.ts), then edited by hand. Put back after a
// regenerate: `jsonb` from shared, timestamps with time zone, the `role` enum, not-null
// `role` and `banned`, the foreign keys on cityId, avatarUploadId and chosenPlanId, the checks, and
// `loginFailures` (ours, not Better-Auth's), `session.secondStep` (ours, 3.7).
import { roleSchema } from "@sayaratak/shared/schemas/fields"
import type { Interest } from "@sayaratak/shared/schemas/user"
import type { NotificationPrefs } from "@sayaratak/shared/schemas/api"
import { relations, sql } from "drizzle-orm"
import {
  type AnyPgColumn,
  bigint,
  boolean,
  check,
  index,
  integer,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core"

import { plans } from "~/modules/plans/plans.tables"
import { cities } from "~/modules/taxonomy/taxonomy.tables"
import { uploads } from "~/modules/uploads/uploads.tables"
import { jsonb } from "~/shared/db/jsonb"

export const role = pgEnum("role", roleSchema.enum)

const at = () => timestamp({ withTimezone: true })
const updatedAt = () =>
  at()
    .$onUpdate(() => new Date())
    .notNull()

// One table for every account (A5). `emailVerified` is the API's `verifiedEmail`, `name` its
// `fullName`, `banReason` and `banExpires` its `bannedReason` and `bannedUntil`.
export const user = pgTable(
  "user",
  {
    id: text().primaryKey(),
    name: text().notNull(),
    email: text().notNull().unique(),
    emailVerified: boolean().default(false).notNull(),
    // Set by Better-Auth from a social provider; the app shows `avatarUploadId`.
    image: text(),
    createdAt: at().notNull(),
    updatedAt: updatedAt(),
    twoFactorEnabled: boolean().default(false),
    role: role().default("user").notNull(),
    banned: boolean().default(false).notNull(),
    banReason: text(),
    banExpires: at(),
    // Normalized by `@sayaratak/shared/lib/phone`, unique when set.
    phone: text(),
    verifiedPhone: boolean().default(false).notNull(),
    avatarUploadId: text().references((): AnyPgColumn => uploads.id, {
      onDelete: "set null",
    }),
    cityId: text().references(() => cities.id, { onDelete: "set null" }),
    locale: text().default("ar").notNull(),
    onboardingDone: boolean().default(false).notNull(),
    interests: text().array().$type<Interest[]>().default([]).notNull(),
    prefs: jsonb().$type<NotificationPrefs>().notNull(),
    // A paid plan picked in onboarding and not paid for yet.
    chosenPlanId: text().references((): AnyPgColumn => plans.id, {
      onDelete: "set null",
    }),
  },
  (table) => [
    uniqueIndex().on(table.phone).where(sql`${table.phone} is not null`),
    // One platform admin (owner rule): a second `role = 'admin'` row is refused by the database.
    uniqueIndex("user_one_admin")
      .on(table.role)
      .where(sql`${table.role} = 'admin'`),
    check("user_email_lower", sql`${table.email} = lower(${table.email})`),
    check("user_locale", sql`${table.locale} in ('ar', 'en')`),
  ]
)

export const session = pgTable(
  "session",
  {
    id: text().primaryKey(),
    expiresAt: at().notNull(),
    token: text().notNull().unique(),
    createdAt: at().notNull(),
    updatedAt: updatedAt(),
    ipAddress: text(),
    userAgent: text(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    impersonatedBy: text(),
    // Set once an admin entered the emailed code (3.7); /admin/* needs it.
    secondStep: boolean().default(false).notNull(),
  },
  (table) => [index().on(table.userId)]
)

export const account = pgTable(
  "account",
  {
    id: text().primaryKey(),
    accountId: text().notNull(),
    providerId: text().notNull(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text(),
    refreshToken: text(),
    idToken: text(),
    accessTokenExpiresAt: at(),
    refreshTokenExpiresAt: at(),
    scope: text(),
    password: text(),
    createdAt: at().notNull(),
    updatedAt: updatedAt(),
  },
  (table) => [index().on(table.userId)]
)

export const verification = pgTable(
  "verification",
  {
    id: text().primaryKey(),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: at().notNull(),
    createdAt: at().notNull(),
    updatedAt: updatedAt(),
  },
  (table) => [index().on(table.identifier)]
)

export const twoFactor = pgTable(
  "two_factor",
  {
    id: text().primaryKey(),
    secret: text().notNull(),
    backupCodes: text().notNull(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    verified: boolean().default(true),
    failedVerificationCount: integer().default(0),
    lockedUntil: at(),
  },
  (table) => [index().on(table.secret), index().on(table.userId)]
)

export const rateLimit = pgTable("rate_limit", {
  id: text().primaryKey(),
  key: text().notNull().unique(),
  count: integer().notNull(),
  lastRequest: bigint({ mode: "number" }).notNull(),
})

// Failed password sign-ins, for the throttle in auth.guard.service.ts (owner, 3.6): per
// email and IP, and per email from every IP. Cleared on a successful sign-in or password
// reset; the prune job drops rows older than a day.
export const loginFailures = pgTable(
  "login_failures",
  {
    email: text().notNull(),
    ip: text().notNull(),
    failedAt: at().notNull(),
  },
  (table) => [index().on(table.email, table.failedAt)]
)

export const userRelations = relations(user, ({ many }) => ({
  sessions: many(session),
  accounts: many(account),
  twoFactors: many(twoFactor),
}))

export const sessionRelations = relations(session, ({ one }) => ({
  user: one(user, { fields: [session.userId], references: [user.id] }),
}))

export const accountRelations = relations(account, ({ one }) => ({
  user: one(user, { fields: [account.userId], references: [user.id] }),
}))

export const twoFactorRelations = relations(twoFactor, ({ one }) => ({
  user: one(user, { fields: [twoFactor.userId], references: [user.id] }),
}))

export type UserRow = typeof user.$inferSelect
export type NewUserRow = typeof user.$inferInsert
